package br.gov.dere.api; import br.gov.dere.persistence.DereValidationAuditRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reports") public class ReportController {private final DereValidationAuditRepository repo; public ReportController(DereValidationAuditRepository r){repo=r;} @GetMapping(value="/{id}",produces="text/plain") public ResponseEntity<String> report(@PathVariable Long id){var a=repo.findById(id).orElseThrow();var body="RELATÓRIO DeRE\nData: "+a.getCreatedAt()+"\nVálido: "+a.isValid()+"\nErros: "+a.getErrors()+"\n\nXML:\n"+a.getPayloadXml()+"\n\nCSV:\n"+a.getPayloadCsv();return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=relatorio-dere-"+id+".txt").body(body);} }
